document.getElementById("screenshot")?.addEventListener("click",(()=>{chrome.tabs.query({active:!0,currentWindow:!0},(e=>{const t=e[0];t.id&&chrome.tabs.sendMessage(t.id,{type:"startScreenshot"})})),window.close()})),document.getElementById("manage")?.addEventListener("click",(()=>{chrome.tabs.query({active:!0,currentWindow:!0},(e=>{const t=e[0];t.id&&chrome.tabs.sendMessage(t.id,{type:"toggleManage"})})),window.close()}));